def calendar_frequency(records,names,first='2025-12-15',end='2026-10-31'):
    a=date.fromisoformat(first);b=date.fromisoformat(end);daily={(a+timedelta(days=i)).isoformat():{n:Counter() for n in names} for i in range((b-a).days)};reasons={n:Counter() for n in names};qualified={n:Counter() for n in names}
    for r in records:
        d=local_day(r['decision']);n=r['lane']
        if d not in daily:raise ValueError('Decision outside reported calendar')
        daily[d][n]['raw']+=1;daily[d][n][r['status']]+=1;reasons[n][r['reason']]+=1
        if r.get('signal_qualified'):daily[d][n]['qualified']+=1;qualified[n][r['status']]+=1
    buckets={k:{} for k in ['weekly','monthly']}
    for d,lanes in daily.items():
        iso=date.fromisoformat(d).isocalendar()
        for k,key in [('weekly',f'{iso.year}-W{iso.week:02d}'),('monthly',d[:7])]:
            v=buckets[k].setdefault(key,{n:Counter() for n in names})
            for n,c in lanes.items():v[n].update(c)
    totals={n:sum((x[n] for x in daily.values()),Counter()) for n in names}
    for n,c in totals.items():assert c['raw']==sum(c[s] for s in ['EXECUTED','REJECTED','BLOCKED','MISSED'])
    return dict(daily=daily,**buckets,totals=totals,reasons=reasons,qualified_status=qualified,calendar_days=len(daily),weekdays=sum(date.fromisoformat(d).weekday()<5 for d in daily),ISO_weeks=len(buckets['weekly']),calendar_months=len(buckets['monthly']),definition='Includes allcalendar dates,includingweekendrawsignals. Qualifiedmeansnoncapitalentrychecks passed,not independentlyprovenprofit. Missingdata slots imply unknownsetups. Monthlybinsinclude partialDecember/October.')


